interface Node<T> { value: T; left: Node<T> | null; right: Node<T> | null; }

export interface BSTOptions {
  onStackPush?: (stackSize: number) => void;
}

export class BST<T> {
  private root: Node<T> | null = null;
  private _size = 0;
  private compare: Comparator<T>;
  private onStackPush?: (n: number) => void;

  constructor(comparator: Comparator<T>, options: BSTOptions = {}) { ... }

  get size() { return this._size; }

