  has(value: T): boolean { walk down }

  delete(value: T): boolean {
    // find node and parent, handle leaf/one-child/two-child (find successor)
  }

  *[Symbol.iterator](): Iterator<T> {
    const stack: Node<T>[] = [];
    let current = this.root;
    while (current || stack.length) {
      while (current) { stack.push(current); this.onStackPush?.(stack.length); current = current.left; }
      const node = stack.pop()!;
