result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "src/bst.ts", "content": "export type Comparator<T> = (a: T, b: T) => number;

interface Node<T> {
  value: T;
  left: Node<T> | null;
  right: Node<T> | null;
}

export interface BSTOptions {
  /**
   * Called every time the in-order iterator pushes a node onto its
   * explicit stack. Injectable for laziness assertions in tests.
   */
  onStackPush?: (stackSize: number) => void;
}

export class BST<T> {
  private root: Node<T> | null = null;
  private _size = 0;
  private readonly compare: Comparator<T>;
  private readonly onStackPush?: (stackSize: number) => void;

  constructor(comparator: Comparator<T>, options: BSTOptions = {}) {
    this.compare = comparator;
    this.onStackPush = options.onStackPush;
  }

  get size(): number {
    return this._size;
  }

  insert(value: T): this {
    const node: Node<T> = { value, left: null, right: null };
    if (!this.root) {
      this.root = node;
      this._size++;
      return this;
    }
    let cur = this.root;
    for (;;) {
      const cmp = this.compare(value, cur.value);
      if (cmp < 0) {
        if (!cur.left) {
          cur.left = node;
          this._size++;
          return this;
        }
        cur = cur.left;
      } else if (cmp > 0) {
        if (!cur.right) {
          cur.right = node;
          this._size++;
          return this;
        }
        cur = cur.right;
      } else {
        // Duplicate under this comparator: ignore.
        return this;
      }
    }
  }

  has(value: T): boolean {
    let cur = this.root;
    while (cur) {
      const cmp = this.compare(value, cur.value);
      if (cmp === 0) return true;
      cur = cmp < 0 ? cur.left : cur.right;
    }
    return false;
  }

  /** Deletes `value` if present. Returns true when a node was removed. */
  delete(value: T): boolean {
    let parent: Node<T> | null = null;
    let cur = this.root;

    // Find the node and its parent.
    while (cur) {
      const cmp = this.compare(value, cur.value);
      if (cmp === 0) break;
      parent = cur;
      cur = cmp < 0 ? cur.left : cur.right;
    }
    if (!cur) return false; // not found

    if (cur.left && cur.right) {
      // Two children: splice the in-order successor (leftmost of right
      // subtree) into `cur` by copying its value, then unlink it.
      let succParent = cur;
      let succ = cur.right;
      while (succ.left) {
        succParent = succ;
        succ = succ.left;
      }
      cur.value = succ.value;
      // `succ` has no left child; replace it with its right child.
      if (succParent.left === succ) succParent.left = succ.right;
      else succParent.right = succ.right;
    } else {
      // Leaf or single child: replace the node with its only child (or null).
      const child = cur.left ?? cur.right;
      if (!parent) this.root = child;
      else if (parent.left === cur) parent.left = child;
      else parent.right = child;
    }

    this._size--;
    return true;
  }

  /**
   * Lazy in-order iterator: explicit stack, no recursion, values are
   * produced one at a time — nothing is materialized up front.
   */
  *[Symbol.iterator](): Generator<T> {
    const stack: Node<T>[] = [];
    let current: Node<T> | null = this.root;

    while (current !== null || stack.length > 0) {
      while (current !== null) {
        stack.push(current);
        this.onStackPush?.(stack.length);
        current = current.left;
      }
      const node = stack.pop() as Node<T>;
      yield node.value;
      current = node.right;
    }
  }
}
"})
