result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "src/bst.test.ts", "content": "import { describe, expect, it } from "vitest";
import { BST } from "./bst.js";

const asc = (a: number, b: number) => a - b;
const desc = (a: number, b: number) => b - a;

function shuffled(n: number): number[] {
  // Deterministic PRNG (mulberry32) so failures are reproducible.
  let seed = 0x2f6e2b1;
  const rand = () => {
    seed |= 0;
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  const xs = Array.from({ length: n }, (_, i) => i * 3 - n); // unique ints
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [xs[i], xs[j]] = [xs[j] as number, xs[i] as number];
  }
  return xs as number[];
}

describe("BST", () => {
  it("iterates in sorted order equal to sorted input (1000 random numbers)", () => {
    const input = shuffled(1000);
    const bst = new BST(asc);
    for (const x of input) bst.insert(x);

    expect(bst.size).toBe(input.length);
    expect([...bst]).toEqual([...input].sort(asc));
  });

  it("supports a descending comparator", () => {
    const input = shuffled(100);
    const bst = new BST(desc);
    for (const x of input) bst.insert(x);

    expect([...bst]).toEqual([...input].sort(desc));
    expect(bst.has(input[0] as number)).toBe(true);
  });

  it("supports a comparator by object field", () => {
    interface Person {
      name: string;
      age: number;
    }
    const byAge = (a: Person, b: Person) => a.age - b.age;
    const people: Person[] = shuffled(50).map((age, i) => ({
      name: `p${i}`,
      age,
    }));

    const bst = new BST(byAge);
    for (const p of people) bst.insert(p);

    expect([...bst]).toEqual([...people].sort(byAge));
    expect(bst.has({ name: "irrelevant", age: people[0]?.age ?? 0 })).toBe(
      true,
    );
  });

  describe("delete", () => {
    it("deletes a leaf", () => {
      const bst = new BST<number>(asc);
      for (const x of [50, 30, 70, 20]) bst.insert(x); // 20 is a leaf

      expect(bst.delete(20)).toBe(true);
      expect(bst.has(20)).toBe(false);
      expect(bst.size).toBe(3);
      expect([...bst]).toEqual([30, 50, 70]);
    });

    it("deletes a node with one child", () => {
      const bst = new BST<number>(asc);
      for (const x of [50, 30, 70, 25]) bst.insert(x); // 30 has only left child 25

      expect(bst.delete(30)).toBe(true);
      expect(bst.has(30)).toBe(false);
      expect(bst.size).toBe(3);
      expect([...bst]).toEqual([25, 50, 70]);
    });

    it("deletes a node with two children", () => {
      const bst = new BST<number>(asc);
      for (const x of [50, 30, 70, 20, 40, 60, 80]) bst.insert(x);

      expect(bst.delete(30)).toBe(true); // successor 40 replaces it
      expect(bst.has(30)).toBe(false);
      expect(bst.size).toBe(6);
      expect([...bst]).toEqual([20, 40, 50, 60, 70, 80]);
    });

    it("returns false when deleting a missing value and keeps the tree intact", () => {
      const bst = new BST<number>(asc);
      for (const x of [10, 5, 15]) bst.insert(x);

      expect(bst.delete(99)).toBe(false);
      expect(bst.size).toBe(3);
      expect([...bst]).toEqual([5, 10, 15]);
    });
  });

  it("iterates an empty tree", () => {
    const bst = new BST<number>(asc);
    expect(bst.size).toBe(0);
    expect([...bst]).toEqual([]);
    // Also safe with spread/for-of/next().
    let count = 0;
    for (const _ of bst) count++;
    expect(count).toBe(0);
    expect(bst[Symbol.iterator]().next().done).toBe(true);
  });

  it("is lazy: taking 3 items from a 10000-node tree barely touches the stack", () => {
    let stackPushes = 0;
    const onStackPush = () => {
      stackPushes++;
    };

    const values = shuffled(10_000);
    const bst = new BST<number>(asc, { onStackPush });
    for (const v of values) bst.insert(v);

    const it = bst[Symbol.iterator]();
    const taken: number[] = [];
    for (let i = 0; i < 3; i++) {
      const r = it.next();
      expect(r.done).toBe(false);
      taken.push(r.value as number);
    }

    // Got the 3 smallest values...
    const expected = [...values].sort(asc).slice(0, 3);
    expect(taken).toEqual(expected);

    // ...while the explicit stack only ever held O(tree depth) nodes —
    // nowhere near the 10000 that full materialization would require.
    expect(stackPushes).toBeLessThan(200);
    expect(stackPushes).toBeLessThan(values.length / 10);
  });
});
"})
